WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 4 OFFSET 1 ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "articles" , "c2"."j" AS "page" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) ORDER BY "t1"."id" ASC NULLS LAST ), '[]') AS "j" FROM ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND "s"."author_id" = "t0"."id" AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST OFFSET 1 ) AS "t1" ) AS "c1" ON true LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) ORDER BY "t1"."id" DESC NULLS FIRST ), '[]') AS "j" FROM ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND "s"."author_id" = "t0"."id" AND ( ( true ) ) ORDER BY "s"."id" DESC NULLS FIRST LIMIT 1 OFFSET 1 ) AS "t1" ) AS "c2" ON true
